//! `.github/jactionlint.yaml` rendering: fixed keys, no suppression keys.
use velnor_actions_actionlint::{ActionlintError, JactionlintConfigInput, render_jactionlint_yaml};
use velnor_actions_contract::WorkflowLintProfile;

const HEADER: &str =
    "# Generated by Velnor Actions 0.1.0; edit .velnor/config.toml and regenerate.\n\n";

#[test]
fn default_bytes_are_the_fixed_template() {
    let yaml = render_jactionlint_yaml(&JactionlintConfigInput::new("0.1.0")).expect("renders");
    assert_eq!(
        yaml,
        format!("{HEADER}profile: correctness\ngenerated-files: report\nconfig-variables: []\n")
    );
}

#[test]
fn every_profile_renders_its_exact_value() {
    for (profile, text) in [
        (WorkflowLintProfile::Correctness, "correctness"),
        (WorkflowLintProfile::Default, "default"),
        (WorkflowLintProfile::Pedantic, "pedantic"),
    ] {
        let input = JactionlintConfigInput::new("0.1.0").with_profile(profile);
        let yaml = render_jactionlint_yaml(&input).expect("renders");
        assert!(yaml.contains(&format!("\nprofile: {text}\n")), "{yaml}");
        assert!(yaml.contains("\ngenerated-files: report\n"), "{yaml}");
    }
}

#[test]
fn keys_render_in_fixed_order_with_sorted_variables_and_custom_labels_only() {
    let input = JactionlintConfigInput::new("0.1.0")
        .with_profile(WorkflowLintProfile::Default)
        .with_config_variables(["ZETA", "ALPHA", "ZETA"])
        .with_runner_labels(["velnor", "ubuntu-26.04", "ubuntu-26.04-scale-set", "velnor"])
        .with_runner_labels(["macos-15", "macos-15-arm64"]);
    let yaml = render_jactionlint_yaml(&input).expect("renders");
    assert_eq!(
        yaml,
        format!(
            "{HEADER}profile: default\ngenerated-files: report\nconfig-variables:\n  - ALPHA\n  - ZETA\nself-hosted-runner:\n  labels:\n    - velnor\n    - ubuntu-26.04-scale-set\n    - macos-15-arm64\n"
        )
    );
    assert_eq!(render_jactionlint_yaml(&input).expect("renders"), yaml);
}

#[test]
fn hosted_only_labels_emit_no_self_hosted_block() {
    let input = JactionlintConfigInput::new("0.1.0").with_runner_labels([
        "ubuntu-26.04",
        "ubuntu-24.04-arm",
        "macos-26-intel",
    ]);
    let yaml = render_jactionlint_yaml(&input).expect("renders");
    assert!(!yaml.contains("self-hosted-runner"), "{yaml}");
}

#[test]
fn no_key_can_turn_a_finding_off() {
    let input = JactionlintConfigInput::new("0.1.0")
        .with_profile(WorkflowLintProfile::Pedantic)
        .with_config_variable("APP_ID")
        .with_runner_labels(["velnor"]);
    let yaml = render_jactionlint_yaml(&input).expect("renders");
    for key in [
        "rules:", "ignores:", "paths:", "baseline", "online", "extends", "skip", "ignore",
    ] {
        assert!(!yaml.contains(key), "{key} in {yaml}");
    }
}

#[test]
fn unsafe_versions_variables_and_labels_fail_closed() {
    for version in ["", "0.1.0 bad", "0.1.0\n"] {
        assert!(matches!(
            render_jactionlint_yaml(&JactionlintConfigInput::new(version)),
            Err(ActionlintError::InvalidGeneratorVersion { .. })
        ));
    }
    for name in ["9LIVES", "GITHUB_TOKEN", "A-B"] {
        let input = JactionlintConfigInput::new("0.1.0").with_config_variable(name);
        assert!(matches!(
            render_jactionlint_yaml(&input),
            Err(ActionlintError::InvalidConfigVariable { .. })
        ));
    }
    for label in ["", "Velnor", "a b", "x:\n  - y"] {
        let input = JactionlintConfigInput::new("0.1.0").with_runner_labels([label]);
        assert!(
            matches!(
                render_jactionlint_yaml(&input),
                Err(ActionlintError::InvalidRunnerLabel { .. })
            ),
            "{label:?}"
        );
    }
}
